For ${\alpha} > -1$ and $s \in {\mathbb N}$,
\begin{equation}\label{eq:Jn(a,-s)}
  J_n^{({\alpha},-s)} (t) = \frac{(n-s)!}{n!}  (1+t)^s \widehat P_{n-s}^{({\alpha},s)}(t), \qquad n \ge s.
\end{equation}
In particular, for $n \ge s$,
\begin{equation}\label{eq:Jn(a,-s)=Pn}
  J_n^{({\alpha},-s)} (t) = \frac{(-1)^s 2^s}{(-{\alpha}-n)_s}A_{n-s}^{({\alpha},s)} P_n^{({\alpha},-s)}(t).
\end{equation}

\label{thm:Jacobi-DE-V0}
Let $d\ge 2$ and ${\gamma} > -1$. The orthogonal polynomials in ${\mathcal V}_n({\mathbb V}_0^{d+1}, {\mathsf w}_{-1,{\gamma}})$ are eigenfunctions
of ${\mathcal D}_{{\gamma}}$; more precisely,
\begin{equation}\label{eq:eigen-eqn}
    {\mathcal D}_{{\gamma}} u =  -n (n+{\gamma}+d-1) u, \qquad \forall u \in {\mathcal V}_n({\mathbb V}_0^{d+1}, {\mathsf w}_{-1,{\gamma}}).
\end{equation}

\label{lem:fD}
For $(x,t) \in {\mathbb V}_0^{d+1})$, let $p(t)$ and $q(x)$ be differentiable functions. Then 
\begin{align} \label{eq:fD1}
     {\mathfrak D} \left[p(t) q(x)\right] = p'(t) q(x). 
\end{align}
In particular, let $ \tau_{m,n} = - (n+m + {\beta}+ {\gamma} + d)$, then
\begin{align} \label{eq:fD_basis}
     {\mathfrak D} {\mathsf S}_{m,\ell}^{n,({\beta},{\gamma})}(x,t) & = \frac{\mathrm{d}}{\mathrm{d} t} \left[P_{n-m}^{(2m + {\beta} + d-1,{\gamma})} (1-2t)\right] Y_\ell^m(x) \\ 
       & =  \tau_{n,m} {\mathsf S}_{m,\ell}^{n-1,({\beta}+1,{\gamma}+1)}(x,t), \qquad 0 \le m \le n-1,  \notag
\end{align}
and, for $m = n$, ${\mathfrak D} {\mathsf S}_{n,\ell}^{n,({\beta},{\gamma})}(x,t) = 0$.

\label{cor:der_sS}
For $0 \le m \le n-s$,
\begin{equation} \label{eq:D_sS}
 {\mathfrak D}^s {\mathsf S}_{m,\ell}^{n, ({\beta},-s)}(x,t) = (-2)^s A_{n-s-m}^{(s+2m+{\beta}+d-1,0)} S_{m,\ell}^{n-s, ({\beta}+s,0)}(x,t),
\end{equation}
and it is equal to zero if $m > n-s$. Moreover, for $1 \le k \le s-1$ and $\xi \in {\mathbb{S}^{d-1}}$,
\begin{equation} \label{eq:D_sS2}
    {\mathfrak D}^k  {\mathsf S}_{m,\ell}^{n, ({\beta},-s)}(\xi,1) = \begin{cases}
         (-2)^k Y_\ell^m(\xi) \delta_{k,n-m}, & m > n-s \\
         0, & m \le n-s.
     \end{cases}
\end{equation}

For $0 \le \ell \le \dim {\mathcal H}_m^d$ and $0 \le m \le n$, the polynomials $S_{m,\ell}^{n,({\beta},-s)}$ satisfy
\begin{equation}\label{eq:sS-explicit}
   {\mathsf S}_{m,\ell}^{n,({\beta},-s)}(x,t) = \begin{cases} b_{m,n}^s  (1- t)^s S_{m,\ell}^{n-s,({\beta},s)}(x,t) & n-m \ge s, \\
           \frac{2^{n-m}}{(n-m)!}  (1-t)^{n-m} Y_\ell^m(x), &  0 \le n-m\le s-1,
\end{cases}
\end{equation}
where $b_{m,n}^s =   (-1)^s 2^s A_{n-s-m}^{(2m+{\beta}+d-1,s)}/{(-n+m)_s}$. In particular, the space ${\mathcal V}_n^d({\mathsf w}_{{\beta},-s})$
satisfies a decomposition
\begin{equation}\label{eq:decompVnd}
  {\mathcal V}_n^d({\mathsf w}_{{\beta},-s}) = \bigoplus_{j=0}^{s-1} (1-t)^j {\mathcal H}_{n-j}^{d,0} \bigoplus (1-t)^s {\mathcal V}_{n-s}^d({\mathsf w}_{{\beta},s}).
\end{equation}

\label{thm:proj-s=int}
Let $s$ be a positive integer. For ${\beta} > -d-s$, let $f$ be a differentiable function such that
${\mathfrak D}^s f \in L^2({\mathbb V}_0^{d+1}, {\mathsf w}_{{\beta}+s,0})$. Then, for $n =0,1,2,\ldots$ and $(x,t) \in {\mathbb V}_0^{d+1}$,
\begin{align}\label{eq:proj-s=int}
   \operatorname{proj}_n^{{\beta},-s} f(x,t) = \,& \sum_{m=0}^{s-1} \frac{(t-1)^m}{m!} \operatorname{proj}_{n-m}^{\mathbb{S}^{d-1}}  \left[{\mathfrak D}^m f(\cdot,1)\right](x) \\

        & + (-1)^s \int_{t}^{1} \frac{(v-t)^{s-1}}{(s-1)!} \operatorname{proj}_{n-s}^{{\beta}+s,0} \left({\mathfrak D}^s f\right) (x, v) \mathrm{d} v. \notag
\end{align}

Let ${\alpha} = s+{\beta}+d-1$. For $0 \le m \le n-s$, it follows from \eqref{eq:D_sS} that
\begin{align*}
\left \langle f,  {\mathsf S}_{m, \ell}^{n,({\beta},-s)}\right \rangle_{{\beta},-s} \,&  =(-2)^s A_{n-s-m}^{(2m+{\alpha},0)}
   \frac{1}{{\omega}_d} \int_{{\mathbb V}_0^{d+1}} {\mathfrak D}^s f(x,t) {\mathsf S}_{m,\ell}^{n-s,({\beta}+s,0)}(x,t) t^{{\beta}+s} \mathrm{d} {\mathsf m}(x,t)\\
         & = (-2)^s A_{n-s-m}^{(2m+{\alpha},0)} \frac{1}{c_{{\alpha},0}}
           \left \langle {\mathfrak D}^s f,  {\mathsf S}_{m, \ell}^{n-s,({\beta}+s,0)}\right \rangle_{{\beta}+s,0}
\end{align*}
and the norm of ${\mathsf S}_{m,\ell}^{n,({\beta},-s)}$ satisfies
\begin{align*}
  {\mathsf h}_{m,n}^{({\beta},-s)} = 2^{s - {\beta}-2m-d} \widehat h_{n-m-s}^{({\alpha}+2m,0)} \, & =
   2^{2s}  \frac{1}{c_{2m+{\alpha},0}} \left[A_{n-m-s}^{(2m+{\alpha},0)}\right]^2 h_{n-s-m}^{(2m+{\alpha},0)} \\
  & = \frac{1}{c_{{\alpha},0}} 2^{2s} \left[A_{n-m-s}^{(2m+{\alpha},0)}\right]^2 \frac{({\alpha}+1)_{2m}}{({\alpha}+2)_{2m}}h_{n-s-m}^{(2m+{\alpha},0)}\\
  & =  \frac{1}{c_{{\alpha},0}} 2^{2s} \left[A_{n-m-s}^{(2m+{\alpha},0)}\right]^2 h_{n-s, m}^{{\beta}+s,0}.
\end{align*}
Consequently, it follows that for $0 \le m \le n-s$,
\begin{equation}\label{eq:FourierCoeffs}
 \hat f_{m,\ell}^{n, ({\beta},-s)} = \frac{ \left \langle {\mathfrak D}^s f,  {\mathsf S}_{m, \ell}^{n-s,({\beta}+s,0)}\right \rangle_{{\beta}+s,0}}
       { (-2)^{s} A_{n-m-s}^{(2m+{\alpha},0)} h_{n-s, m}^{{\beta}+s,0}}
        = \frac{ \widehat{{\mathfrak D}^s f}_{m,\ell}^{n-s, ({\beta}+s,0)}}{(-2)^{s} A_{n-m-s}^{(2m+{\alpha},0)}}.
\end{equation}
Now, for $n-s < m \le n$, it follows by Corollary \ref{cor:der_sS} that
\begin{align*}
\left \langle f, {\mathsf S}_{m, \ell}^{n,({\beta},-s)}\right \rangle_{{\beta},-s}
\,& = \sum_{k=0}^{s-1} \frac{{\lambda}_k}{{\omega}_d} \int_{{\mathbb{S}^{d-1}}} {\mathfrak D}^k f(\xi,1) {\mathfrak D}^k  {\mathsf S}_{m, \ell}^{n,({\beta},-s)}(\xi,1)\mathrm{d} \sigma(\xi) \\
 & = (-2)^{n-m} \frac{{\lambda}_{n-m}}{{\omega}_d} \int_{{\mathbb{S}^{d-1}}}{\mathfrak D}^{n-m} f(\xi,1) Y_\ell^{m} (\xi)\mathrm{d} \sigma(\xi),
\end{align*}
so that, using the norm of ${\mathsf h}_{n,m}^{({\beta},-s)}$ in Theorem \ref{thm:SOP-cone},
$$
\hat f_{m,\ell}^{n, ({\beta},-s)} = \frac{1}{(-2)^{n-m}} \frac{1}{{\omega}_d} \int_{{\mathbb{S}^{d-1}}} {\mathfrak D}^{n-m} f(\xi,1) Y_\ell^{m} (\xi)\mathrm{d} \sigma(\xi),
   \quad 0\le n-m \le s-1.
$$
These allow us to expand $\operatorname{proj}_n^{{\beta},-s} f$, for which we split the sum over $\sum_{m=0}^n$ into two parts. We make 
a change of variable for the first sum $\sum_{m=n-s}^n B_m = \sum_{m=0}^{s-1} B_{n-m}$ and write the polynomial 
${\mathsf S}_{n-m,\ell}^{n, ({\beta},-s)}$ using the second case of \eqref{eq:sS-explicit}, whereas for the second sum $\sum_{m=0}^{n-s} B_m$
we use the integal form in \eqref{eq:CJ} in ${\mathsf S}_{n-m,\ell}^{n, ({\beta},-s)}$. We then obtain, using ${\alpha} = s+{\beta}+d-1$ again, 
\begin{align*}
 & \operatorname{proj}_n^{{\beta},-s} f(x,t) \, = \sum_{m=0}^{s-1} \frac{(t-1)^m}{m!}
      \sum_{\ell=1}^{\dim {\mathcal H}_{n-m}^d} \frac{1}{{\omega}_d} \int_{{\mathbb{S}^{d-1}}}
         {\mathfrak D}^{m} f(\eta,1) Y_\ell^{n-m} (\eta)\mathrm{d} \sigma(\eta)\,Y_\ell^{n-m} (x) \\
   & \qquad\quad
    + \sum_{m = 0}^{n-s} \sum_{\ell=1}^{\dim {\mathcal H}_{m}^d}
       \frac{ \widehat{{\mathfrak D}^s f}_{m,\ell}^{n-s, ({\beta}+s,0)}}{(-2)^{s} A_{n-m-s}^{(2m+{\alpha},0)}}
        \int_{-1}^{1-2t} \frac{(1-2t -u)^{s-1}}{(s-1)!} \widehat P_{n-s}^{({\alpha}+2m,0)}(u) \mathrm{d} u \, Y_\ell^m(x).
 \end{align*}
The inner sum of the first term on the right-hand side is
$$
t^{n-m} \operatorname{proj}_{n-m}^{\mathbb{S}^{d-1}} [{\mathfrak D}^m f(\cdot,1)](\xi) = \operatorname{proj}_{n-m}^{\mathbb{S}^{d-1}} [{\mathfrak D}^m f(\cdot,1)](x),
$$
since the function $\xi \mapsto {\mathfrak D}^m f(\xi,1)$ on the unit sphere and $\operatorname{proj}_{n-m}^{\mathbb{S}^{d-1}}$ are homogeneous of degree
$n-m$. Changing variable $u = 1-2v$ and using \eqref{eq:JacobiJ} in the integral, the second term on the right-hand side becomes,
\begin{align*}
  \sum_{m = 0}^{n-s} \sum_{\ell} & \widehat{{\mathfrak D}^s f}_{m,\ell}^{n-s, ({\beta}+s,0)}  (-1)^s
        \int_{t}^{1} \frac{(v-t)^{s-1}}{(s-1)!} P_{n-s}^{({\alpha}+2m,0)}(1-2v) \mathrm{d} v \, Y_\ell^m(x) \\
   & = (-1)^s  \int_{t}^{1}  \frac{(v-t)^{s-1}}{(s-1)!}  \sum_{m = 0}^{n-s} \sum_{\ell}
     \widehat{{\mathfrak D}^s f}_{m,\ell}^{n-s, ({\beta}+s,0)}  {\mathsf S}_{m,\ell}^{n-s, ({\beta}+s,0)} (x,v) \mathrm{d} v\\
  &  =  (-1)^s \int_{t}^{1} \frac{(v-t)^{s-1}}{(s-1)!} \operatorname{proj}_{n-s}^{{\beta}+s,0}{\mathfrak D}^s f (x, v) \mathrm{d} v.
\end{align*}
Putting the two terms together completes the proof.

\label{thm:errorSOP}
For $f \in C^s({\mathbb V}_0^{d+1})$,
\begin{align*}
  f(x,t) - {\mathsf Q}_{n,\eta}^{(\beta, -s)}f(x,t)  \,& = \sum_{m=0}^{s-1} \frac{(t-1)^m}{m!} \left[ {\mathfrak D}^m f(x,,1)
     - {\mathsf Q}_{n-m,\eta}^{{\mathbb{S}^{d-1}}} \left[{\mathfrak D}^m f(\cdot,1)\right](x) \right] \\
   & +  (-1)^s \int_{t}^{1} \frac{(v-t)^{s-1}}{(s-1)!} \left[ {\mathfrak D}^s f (x, v)-
      {\mathsf Q}_{n-s,\eta}^{{\beta}+s,0}\left({\mathfrak D}^s f\right) (x, v) \right] \mathrm{d} v.
\end{align*}

Let $f \in L^p({\mathbb V}_0^{d+1},{\mathsf w}_{{\beta},0})$ and $f(t) = (1-t) g(t)$. Then, for $1 \le p \le \infty$,
$$
   \left \| f - {\mathsf Q}_{n,\eta}^{(\beta, -s)} f \right\|_{p, {\mathsf w}_{{\beta},0}}
    \le c E_n\left(g \right)_{p, {\mathsf w}_{{\beta},s}} \le c E_n\left(g \right)_{p, {\mathsf w}_{{\beta},0}}
$$

Let $p(t)$ be a polynomial in the $t$ variable and $Y(\xi)$ be a function defined on the unit sphere ${\mathbb{S}^{d-1}}$.
For $k \geq 1$,
\begin{align}\label{eq:D_gamma}
{\mathcal D}_{\gamma} \left [(1-t)^k\,p(t) Y(\xi) \right] \, & = (1-t)^k {\mathcal D}_{\gamma+2k}\left [p(t) Y (\xi)\right] \\
& - k\,(1-t)^{k-1} [d-1-(d+{\gamma}+k-1)t] p(t)Y(\xi). \notag
\end{align}

\label{thm:Z}
For $0\le  j \le n$, let $Z_{j,n}(x,t) = p(t) Y(x)$ with $p$ being a polynomial of degree $j$ in one variable and
$Y$ be a solid harmonic polynomial in ${\mathcal H}_{n-j}^{d,0}$. For $\gamma \in {\mathbb R}$, the only polynomial $p$ for
which $Z_{j,n}$ satisfies
\begin{equation}\label{eq:Z}
     {\mathcal D}_{{\gamma}} Z (x,t) = \lambda_n^{(\gamma)} Z(x,t),  \qquad {\lambda}_n^{({\gamma})} =  -n(n+{\gamma}+d-1),
\end{equation}
is the Jacobi polynomial $p(t) = c_j\,P_j^{(2n-2j+d-2, \gamma)}(1-2t)$, where $c_j$ is an appropriate constant,
if $2n+\gamma+d-r-1\neq 0$ for $0\leq r\leq j$.

For $s = 2,3,\ldots$, define
\begin{align*}
{\mathcal U}_n^d({\mathsf w}_{-1,-s}):= {\mathcal H}_{n}^{d,0}  \bigcup_{j=1}^{s-1}P_j^{(2n-2j+d-2,-s)}(1-2t){\mathcal H}_{n-j}^{d,0}
     \cup (1-t)^s {\mathcal V}_{n-s}^d ({\mathsf w}_{-1,s}).
\end{align*}
Then ${\mathcal U}_n^d({\mathsf w}_{-1,-s})$ is the eigenspace of ${\mathcal D}_{-s}$; more precisely,
${\mathcal D}_{-s} Z=\lambda_n^{(-s)}Z$ for all $Z \in {\mathcal U}_n^d({\mathsf w}_{-1,-s})$. Moreover, the space satisfies
$$
  \dim {\mathcal U}_n^d({\mathsf w}_{-1,-s}) = \binom{n+d-1}{d}
$$
if $-2n-d+j+s+2$ is not a positive integer between 1 and $j$ for $1 \le j \le s-1$ and $n \ge j$.
